                    parse_error(f"expected parameter for argument {arepr}")
                if i + 1 >= len(argv) or argv[i+1] == "":
                    parse_error(f"expected parameter for argument {arepr}")
                val = argv[i+1]
                if ch == 'q': set_quality(opts, parse_quality_value(val))
                elif ch == 'w': set_lgwin(opts, parse_lgwin_value(val, False), False)
                elif ch == 'o': set_output(opts, val, '-o')
                elif ch == 'C': set_comment(opts, val, '-C')
                elif ch == 'D': set_dictionary(opts, val, '-D')
                elif ch == 'S': set_suffix(opts, val, '-S')
                i += 1
                j += 1
                break
            elif ch == 'c':
                if opts.mode == 'test': opts.test_conflict = True
                set_stdout(opts)
            elif ch == 'd':
                set_mode(opts, 'decompress', '-d')
            elif ch == 'f':
                if opts.force_set: parse_error("force output overwrite already set")
                opts.force = True; opts.force_set = True
            elif ch == 'h':
                sys.stderr.write(help_text()); raise SystemExit(0)
            elif ch == 'j':
                set_keep_rm(opts, True)
            elif ch == 's':
                if opts.squash_set: parse_error("argument --squash / -s already set")
                opts.squash = True; opts.squash_set = True
            elif ch == 'k':
                set_keep_rm(opts, False)
            elif ch == 'n':
                if opts.copy_stat_set: parse_error("argument --no-copy-stat / -n already set")
                opts.copy_stat = False; opts.copy_stat_set = True
            elif ch == 't':
                if opts.stdout_set or opts.concatenated: opts.test_conflict = True
                set_mode(opts, 'test', '-t')
            elif ch == 'v':
                if opts.verbose_set: parse_error("argument --verbose / -v already set")
                opts.verbose = True; opts.verbose_set = True
            elif ch == 'K':
                if opts.mode == 'test': opts.test_conflict = True
                if opts.concatenated_set: parse_error("argument -K / --concatenated already set")
                opts.concatenated = True; opts.concatenated_set = True
            elif ch == 'V':
                sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
            elif ch == 'Z':
                set_quality(opts, 11)
            else:
                parse_error(f"invalid argument -{ch}")
            j += 1
        i += 1

    # Silent validation failures in the reference print just the usage block.
    if opts.mode == 'test' and (opts.stdout_set or opts.concatenated or opts.test_conflict):
        parse_error(None)
    if opts.stdout and len(opts.files) > 1:
        parse_error(None)
    if opts.squash and opts.stdout:
        parse_error(None)
    return opts

class Brotli:
    def __init__(self):
        self.enc = ctypes.CDLL('libbrotlienc.so.1')
        self.dec = ctypes.CDLL('libbrotlidec.so.1')
        self.enc.BrotliEncoderCreateInstance.argtypes = [c_void_p, c_void_p, c_void_p]
        self.enc.BrotliEncoderCreateInstance.restype = c_void_p
        self.enc.BrotliEncoderDestroyInstance.argtypes = [c_void_p]
        self.enc.BrotliEncoderSetParameter.argtypes = [c_void_p, c_int, c_uint]
        self.enc.BrotliEncoderSetParameter.restype = c_int
        self.enc.BrotliEncoderCompressStream.argtypes = [c_void_p, c_int, POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t)]
        self.enc.BrotliEncoderCompressStream.restype = c_int
        self.enc.BrotliEncoderIsFinished.argtypes = [c_void_p]
        self.enc.BrotliEncoderIsFinished.restype = c_int
        self.dec.BrotliDecoderCreateInstance.argtypes = [c_void_p, c_void_p, c_void_p]
        self.dec.BrotliDecoderCreateInstance.restype = c_void_p
        self.dec.BrotliDecoderDestroyInstance.argtypes = [c_void_p]
        self.dec.BrotliDecoderSetParameter.argtypes = [c_void_p, c_int, c_uint]
        self.dec.BrotliDecoderSetParameter.restype = c_int
        self.dec.BrotliDecoderDecompressStream.argtypes = [c_void_p, POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t)]
        self.dec.BrotliDecoderDecompressStream.restype = c_int

    def _set_param(self, st, param, value):
        return self.enc.BrotliEncoderSetParameter(st, param, value)

    def compress(self, data, quality, lgwin, use_large=False, comment=None):
        q_eff = 11 if quality == 10 else quality
        if len(data) == 0 and not comment:
            return empty_stream_bytes(quality, q_eff, lgwin, use_large)
        st = self.enc.BrotliEncoderCreateInstance(None, None, None)
        if not st:
            raise RuntimeError('encoder create failed')
        try:
            # BrotliEncoderParameter: MODE=0, QUALITY=1, LGWIN=2, SIZE_HINT=5,
            # LARGE_WINDOW=6. These are stable public API values.
            self._set_param(st, 1, q_eff)
            self._set_param(st, 2, lgwin)
            if use_large:
                self._set_param(st, 6, 1)
            self._set_param(st, 5, min(len(data), 0xffffffff))
            out_parts = []
            def call_stream(op, payload):
                arr = (c_uint8 * max(1, len(payload))).from_buffer_copy(payload if payload else b'\0')
                next_in = ctypes.cast(arr, POINTER(c_uint8))
                avail_in = c_size_t(len(payload))
                while True:
                    outbuf = (c_uint8 * 65536)()
                    next_out = ctypes.cast(outbuf, POINTER(c_uint8))
                    avail_out = c_size_t(65536)
                    total = c_size_t(0)
                    ok = self.enc.BrotliEncoderCompressStream(st, op, byref(avail_in), byref(next_in), byref(avail_out), byref(next_out), byref(total))
                    produced = 65536 - avail_out.value
                    if produced:
                        out_parts.append(bytes(outbuf[:produced]))
                    if not ok:
                        raise RuntimeError('compression failed')
                    if avail_in.value == 0 and avail_out.value > 0:
                        break
            if comment:
                call_stream(BROTLI_OPERATION_EMIT_METADATA, comment)
            arr = (c_uint8 * max(1, len(data))).from_buffer_copy(data if data else b'\0')
            next_in = ctypes.cast(arr, POINTER(c_uint8))
            avail_in = c_size_t(len(data))
            while not self.enc.BrotliEncoderIsFinished(st):
                outbuf = (c_uint8 * 65536)()
                next_out = ctypes.cast(outbuf, POINTER(c_uint8))
                avail_out = c_size_t(65536)
                total = c_size_t(0)
                ok = self.enc.BrotliEncoderCompressStream(st, BROTLI_OPERATION_FINISH, byref(avail_in), byref(next_in), byref(avail_out), byref(next_out), byref(total))
                produced = 65536 - avail_out.value
                if produced:
                    out_parts.append(bytes(outbuf[:produced]))
                if not ok:
                    raise RuntimeError('compression failed')
            return b''.join(out_parts)
        finally:
            self.enc.BrotliEncoderDestroyInstance(st)

    def decompress_one(self, data):
        st = self.dec.BrotliDecoderCreateInstance(None, None, None)
        if not st:
            raise RuntimeError('decoder create failed')
        try:
            # Enable non-RFC large-window streams; the reference decoder accepts
            # them without requiring the flag on the command line.
            self.dec.BrotliDecoderSetParameter(st, 1, 1)
            arr = (c_uint8 * max(1, len(data))).from_buffer_copy(data if data else b'\0')
            base_addr = ctypes.addressof(arr)
            next_in = ctypes.cast(arr, POINTER(c_uint8))
            avail_in = c_size_t(len(data))
            out_parts = []
            while True:
                outbuf = (c_uint8 * 65536)()
                next_out = ctypes.cast(outbuf, POINTER(c_uint8))
                avail_out = c_size_t(65536)
                total = c_size_t(0)
                res = self.dec.BrotliDecoderDecompressStream(st, byref(avail_in), byref(next_in), byref(avail_out), byref(next_out), byref(total))
                produced = 65536 - avail_out.value
                if produced:
                    out_parts.append(bytes(outbuf[:produced]))
                if res == BROTLI_DECODER_RESULT_SUCCESS:
                    cur_addr = ctypes.cast(next_in, c_void_p).value or base_addr
                    consumed = cur_addr - base_addr
                    return True, b''.join(out_parts), consumed
                if res == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT:
                    continue
                if res == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT:
                    cur_addr = ctypes.cast(next_in, c_void_p).value or base_addr
                    consumed = cur_addr - base_addr
                    return False, b''.join(out_parts), consumed
                # ERROR
                cur_addr = ctypes.cast(next_in, c_void_p).value or base_addr
                consumed = max(0, cur_addr - base_addr)
                return False, b''.join(out_parts), consumed
        finally:
            self.dec.BrotliDecoderDestroyInstance(st)

    def decompress(self, data, concatenated=False):
        pos = 0
        out_parts = []
        if concatenated:
            while pos < len(data):
                ok, out, consumed = self.decompress_one(data[pos:])
                out_parts.append(out)
                if not ok or consumed <= 0:
                    return False, b''.join(out_parts), pos + max(consumed, 0)
                pos += consumed
            return True, b''.join(out_parts), pos
        ok, out, consumed = self.decompress_one(data)
        if not ok:
            return False, out, consumed
        if consumed != len(data):
            return False, out, consumed
        return True, out, consumed


def auto_lgwin(n):
    if n <= 0:
        return 10
    w = (n + 15).bit_length()  # ceil(log2(n + 16))
    if w < 10:
        w = 10
    if w > 24:
        w = 24
    return w


def empty_stream_bytes(orig_quality, q_eff, w, use_large):
    if use_large and w > 24:
        if orig_quality <= 2:
            return bytes([0x3f])
        return bytes([0x11, 0xC0 + w])
    if q_eff <= 1:
        if w <= 18:
            return bytes([0x33])
        return bytes([0x33 + 2 * (w - 18)])
    if 10 <= w <= 15:
        return bytes([0xA1 + 0x10 * (w - 10), 0x01])
    if w == 16:
        return bytes([0x06])
    if w == 17:
        return bytes([0x81, 0x01])
    if w <= 18:
        return bytes([0x33])
    return bytes([0x33 + 2 * (w - 18)])


def effective_window(opts, input_len):
    if opts.lgwin is None or opts.lgwin == 0:
        return auto_lgwin(input_len), False
    use_large = opts.large_window and opts.lgwin > 24
    return opts.lgwin, use_large

# Practical extractor for the initial metadata block emitted by the encoder for
# --comment (length <= 80). The public decoder discards metadata, so validation
# needs this lightweight header recognizer.
def extract_initial_metadata(data):
    n = len(data)
    # Large-window metadata, quality >= 3: 11 99..9e LL ... payload at 4.
    if n >= 4 and data[0] == 0x11 and 0x99 <= data[1] <= 0x9e and (data[2] & 0x0f) == 0x05:
        l = ((data[2] >> 4) | (data[3] << 4)) + 1
        if 1 <= l <= 80 and n >= 4 + l:
            return True, data[4:4+l]
    # Window 16 metadata: byte0 is 0x2c or 0xac; length low bit is byte0 bit7.
    if n >= 2 and (data[0] & 0x7f) == 0x2c:
        l = (((data[0] >> 7) & 1) | (data[1] << 1)) + 1
        if 1 <= l <= 80 and n >= 2 + l:
            return True, data[2:2+l]
    # Windows 10..15 and 17: length low three bits live in byte1 bits 5..7.
    if n >= 3 and (data[1] & 0x1f) == 0x0b:
        l = ((data[1] >> 5) | (data[2] << 3)) + 1
        if 1 <= l <= 80 and n >= 3 + l:
            return True, data[3:3+l]
    # Low-quality/small-window and windows 18..24: length low six bits in byte1.
    if n >= 3 and data[0] in (0x63,0x65,0x67,0x69,0x6b,0x6d,0x6f) and (data[1] & 0x03) == 0x01:
        l = ((data[1] >> 2) | (data[2] << 6)) + 1
        if 1 <= l <= 80 and n >= 3 + l:
            return True, data[3:3+l]
    return False, None


def file_error(kind, path, exc):
    sys.stderr.write(f"failed to open {kind} file [{path}]: {exc.strerror or str(exc)}\n")


def read_file(path):
    try:
        with open(path, 'rb') as f:
            return f.read()
    except OSError as e:
        file_error('input', path, e)
        return None


def check_output_available(path, force):
    if not force and os.path.exists(path):
        sys.stderr.write(f"failed to open output file [{path}]: File exists\n")
        return False
    # Try opening later; parent/permission errors are reported then.
    return True


def write_output_file(path, data, force):
    mode = 'wb' if force else 'xb'
    try:
        with open(path, mode) as f:
            f.write(data)
        return True
    except OSError as e:
        file_error('output', path, e)
        return False


def derive_decompress_name(path, suffix):
    if len(path) <= len(suffix):
        sys.stderr.write(f"empty output file name for [{path}] input file\n")
        return None
    if not path.endswith(suffix):
        sys.stderr.write(f"input file [{path}] suffix mismatch\n")
        return None
    out = path[:-len(suffix)]
    if out == '':
        sys.stderr.write(f"empty output file name for [{path}] input file\n")
        return None
    return out


def copy_stat(src, dst):
    try:
        shutil.copystat(src, dst, follow_symlinks=True)
    except Exception:
        pass


def verbose_line(kind, label, in_size, out_size, start):
    elapsed = time.time() - start
    # The original rounds to two decimals; benchmark actions are small, so this
    # usually prints 0.00 just like the reference.
    sys.stderr.write(f"{kind} [{label}]: {in_size} B -> {out_size} B in {elapsed:.2f} sec\n")


def process(opts):
    # Open dictionary file for matching diagnostics. The system public library
    # used here has no custom raw-dictionary entry points, so the data is not
    # otherwise consumed; normal Brotli behavior is preserved for the common CLI.
    if opts.dictionary_path is not None:
        try:
            with open(opts.dictionary_path, 'rb') as f:
                _ = f.read()
        except OSError as e:
            sys.stderr.write(f"failed to open dictionary file [{opts.dictionary_path}]: {e.strerror or str(e)}\n")
            return 1
    br = Brotli()
    files = opts.files if opts.files else ['-']
    rc = 0
    for entry in files:
        is_stdin = (entry == '-')
        label = 'con' if is_stdin else entry
        if is_stdin:
            try:
                data = sys.stdin.buffer.read()
            except Exception as e:
                sys.stderr.write(f"failed to read input [con]: {e}\n")
                return 1
        else:
            data = read_file(entry)
            if data is None:
                return 1

        start = time.time()
        cmd = opts.command
        out_to_stdout = False
        out_path = None
        if cmd == 'test':
            out_to_stdout = False
        elif opts.output is not None:
            out_path = opts.output
        elif opts.stdout or is_stdin:
            out_to_stdout = True
        elif cmd == 'compress':
            out_path = entry + opts.suffix
        else:
            out_path = derive_decompress_name(entry, opts.suffix)
            if out_path is None:
                return 1

        if out_path is not None:
            if not check_output_available(out_path, opts.force):
                return 1

        if cmd == 'compress':
            w, use_large = effective_window(opts, len(data))
            comment = opts.comment if (opts.comment_set and opts.comment) else None
            try:
                out = br.compress(data, opts.quality, w, use_large, comment)
            except Exception:
                sys.stderr.write(f"failed to compress input [{label}]\n")
                return 1
            kept_output = True
            if opts.squash and out_path is not None and len(out) > len(data):
                # Destination is suppressed/removed if it would be larger.
                try:
                    if os.path.exists(out_path):
                        os.remove(out_path)
                except Exception:
                    pass
                kept_output = False
            elif out_to_stdout:
                try:
                    sys.stdout.buffer.write(out)
                    sys.stdout.buffer.flush()
                except BrokenPipeError:
                    return 1
            elif out_path is not None:
                if not write_output_file(out_path, out, opts.force):
                    return 1
                if opts.copy_stat and not is_stdin:
                    copy_stat(entry, out_path)
            if opts.verbose:
                verbose_line('Compressed', label, len(data), len(out), start)
            if opts.remove and kept_output and not is_stdin:
                try: os.remove(entry)
                except OSError: pass
        else:
            # Comment validation: absent comments are reported as "corrupt" but
            # (quirkily) do not cause a failing status; mismatches do fail.
            absent_comment_warning = False
            if opts.comment_set and opts.comment:
                found, meta = extract_initial_metadata(data)
                if found:
                    if meta != opts.comment:
                        sys.stderr.write(f"corrupt input [{label}]\n")
                        return 1
                else:
                    absent_comment_warning = True
            ok, out, consumed = br.decompress(data, opts.concatenated)
            if not ok:
                if out_to_stdout:
                    try:
                        sys.stdout.buffer.write(out); sys.stdout.buffer.flush()
                    except BrokenPipeError:
                        return 1
                sys.stderr.write(f"corrupt input [{label}]\n")
                return 1
            if cmd != 'test':
                if out_to_stdout:
                    try:
                        sys.stdout.buffer.write(out); sys.stdout.buffer.flush()
                    except BrokenPipeError:
                        return 1
                elif out_path is not None:
                    if not write_output_file(out_path, out, opts.force):
                        return 1
                    if opts.copy_stat and not is_stdin:
                        copy_stat(entry, out_path)
            if opts.verbose:
                verbose_line('Decompressed', label, len(data), len(out), start)
            if absent_comment_warning:
                sys.stderr.write(f"corrupt input [{label}]\n")
            if opts.remove and not is_stdin:
                try: os.remove(entry)
                except OSError: pass
    return rc


def main():
    try:
        opts = parse_args(sys.argv[1:])
    except ParseExit as e:
        if e.help_to_stdout:
            sys.stdout.write(help_text())
        else:
            sys.stderr.write(help_text())
        if e.msg:
            sys.stderr.write(str(e.msg) + "\n")
        return e.code
    return process(opts)

if __name__ == '__main__':
    try:
        sys.exit(main())
    except SystemExit:
        raise
    except Exception as e:
        sys.stderr.write(str(e) + "\n")
        sys.exit(1)
