#!/usr/bin/env python3
import sys, os, time, ctypes, math, base64, binascii, shutil
from ctypes import c_void_p, c_int, c_uint, c_size_t, c_uint8, POINTER, byref

VERSION = "brotli 1.2.0"
DEFAULT_SUFFIX = ".br"

# Error/result constants from the public Brotli C API.
BROTLI_OPERATION_PROCESS = 0
BROTLI_OPERATION_FLUSH = 1
BROTLI_OPERATION_FINISH = 2
BROTLI_OPERATION_EMIT_METADATA = 3
BROTLI_DECODER_RESULT_ERROR = 0
BROTLI_DECODER_RESULT_SUCCESS = 1
BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT = 2
BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT = 3

HELP_TEMPLATE = """Usage: {prog} [OPTION]... [FILE]...
Options:
  -#                          compression level (0-9)
  -c, --stdout                write on standard output
  -d, --decompress            decompress
  -f, --force                 force output file overwrite
  -h, --help                  display this help and exit
  -j, --rm                    remove source file(s)
  -s, --squash                remove destination file if larger than source
  -k, --keep                  keep source file(s) (default)
  -n, --no-copy-stat          do not copy source file(s) attributes
  -o FILE, --output=FILE      output file (only if 1 input file)
  -q NUM, --quality=NUM       compression level (0-11)
  -t, --test                  test compressed file integrity
  -v, --verbose               verbose mode
  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)
                              window size = 2**NUM - 16
                              0 lets compressor choose the optimal value
  --large_window=NUM          use incompatible large-window brotli
                              bitstream with window size (0, 10-30)
                              WARNING: this format is not compatible
                              with brotli RFC 7932 and may not be
                              decodable with regular brotli decoders
  -C B64, --comment=B64       set comment; argument is base64-decoded first;
                              (maximal decoded length: 80)
                              when decoding: check stream comment;
                              when encoding: embed comment (fingerprint)
  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary
  -K, --concatenated          allows concatenated brotli streams as input
  -S SUF, --suffix=SUF        output file suffix (default:'.br')
  -V, --version               display version and exit
  -Z, --best                  use best compression level (11) (default)
Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.
With no FILE, or when FILE is -, read standard input.
All arguments after '--' are treated as files.
"""

def help_text():
    return HELP_TEMPLATE.format(prog=os.path.basename(sys.argv[0]) or "executable")

class ParseExit(Exception):
    def __init__(self, code=1, msg=None, help_to_stdout=True):
        super().__init__(msg)
        self.code = code
        self.msg = msg
        self.help_to_stdout = help_to_stdout

def parse_error(msg=None, help_to_stdout=True):
    raise ParseExit(1, msg, help_to_stdout)

class Options:
    def __init__(self):
        self.mode = None  # None means compression; otherwise 'decompress' or 'test'
        self.stdout = False
        self.stdout_set = False
        self.force = False
        self.force_set = False
        self.remove = False
        self.keep_rm_set = False
        self.squash = False
        self.squash_set = False
        self.copy_stat = True
        self.copy_stat_set = False
        self.output = None
        self.quality = 11
        self.quality_set = False
        self.verbose = False
        self.verbose_set = False
        self.lgwin = None
        self.lgwin_set = False
        self.large_window = False
        self.comment = None
        self.comment_set = False
        self.dictionary_path = None
        self.dictionary_set = False
        self.concatenated = False
        self.concatenated_set = False
        self.suffix = DEFAULT_SUFFIX
        self.suffix_set = False
        self.files = []
        self.test_conflict = False

    @property
    def command(self):
        return self.mode or 'compress'


def is_canonical_uint(s):
    if s == "0":
        return True
    return bool(s) and s[0] in "123456789" and all(ch.isdigit() for ch in s)

def parse_quality_value(s):
    if not is_canonical_uint(s):
        parse_error(f"error parsing quality value [{s}]")
    v = int(s)
    if v < 0 or v > 11:
        parse_error(f"error parsing quality value [{s}]")
    return v

def parse_lgwin_value(s, large=False):
    if not is_canonical_uint(s):
        parse_error(f"error parsing lgwin value [{s}]")
    v = int(s)
    maxv = 30 if large else 24
    if v != 0 and v < 10:
        parse_error(f"lgwin parameter ({v}) smaller than the minimum (10)")
    if v > maxv:
        parse_error(f"error parsing lgwin value [{s}]")
    return v

def decode_comment(s):
    # The reference tool accepts unpadded Base64 and ignores ASCII whitespace.
    # A dangling single base64 digit produces no decoded byte (e.g. "A").
    compact = ''.join(ch for ch in s if ch not in ' \t\r\n')
    # Validate padding placement and alphabet for the significant portion.
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/="
    for ch in compact:
        if ch not in alphabet:
            raise ValueError
    if '=' in compact:
        first = compact.find('=')
        if any(ch != '=' for ch in compact[first:]) or len(compact) - first > 2:
            raise ValueError
    # If the length is 1 modulo 4 the last sextet cannot produce a byte; the
    # original effectively ignores it for one-character cases.
    if len(compact) % 4 == 1:
        compact = compact[:-1]
    pad = (-len(compact)) % 4
    try:
        out = base64.b64decode(compact + ('=' * pad), validate=True)
    except Exception:
        raise ValueError
    if len(out) > 80:
        raise ValueError
    return out


def set_quality(opts, value):
    if opts.quality_set:
        parse_error("quality already set")
    opts.quality = value
    opts.quality_set = True

def set_mode(opts, mode, argrepr):
    if opts.mode is not None:
        parse_error(f"command already set when parsing {argrepr}")
    opts.mode = mode

def set_stdout(opts):
    # If an output file was already requested, the reference ignores a later
    # stdout flag. Otherwise duplicates are rejected.
    if opts.output is not None:
        return
    if opts.stdout_set:
        parse_error("write to standard output already set")
    opts.stdout = True
    opts.stdout_set = True

def set_keep_rm(opts, remove):
    if opts.keep_rm_set:
        parse_error("argument --rm / -j or --keep / -k already set")
    opts.remove = remove
    opts.keep_rm_set = True

def set_lgwin(opts, value, large):
    if opts.lgwin_set:
        parse_error("lgwin parameter already set")
    opts.lgwin = value
    opts.large_window = bool(large)
    opts.lgwin_set = True

def set_output(opts, value, argrepr):
    if value == "":
        if argrepr.startswith('--'):
            parse_error(f"must pass the parameter as {argrepr}=value")
        parse_error(f"expected parameter for argument {argrepr}")
    if opts.stdout_set:
        parse_error(f"write to standard output already set ({argrepr})")
    opts.output = value

def set_suffix(opts, value, argrepr):
    if value == "":
        if argrepr.startswith('--'):
            parse_error(f"must pass the parameter as {argrepr}=value")
        parse_error(f"expected parameter for argument {argrepr}")
    if opts.suffix_set:
        parse_error("suffix already set")
    opts.suffix = value
    opts.suffix_set = True

def set_comment(opts, value, argrepr):
    if value == "":
        if argrepr.startswith('--'):
            parse_error(f"must pass the parameter as {argrepr}=value")
        parse_error(f"expected parameter for argument {argrepr}")
    if opts.comment_set:
        parse_error("comment already set")
    try:
        opts.comment = decode_comment(value)
    except Exception:
        parse_error("invalid base64-encoded comment")
    opts.comment_set = True

def set_dictionary(opts, value, argrepr):
    if value == "":
        if argrepr.startswith('--'):
            parse_error(f"must pass the parameter as {argrepr}=value")
        parse_error(f"expected parameter for argument {argrepr}")
    if opts.dictionary_set:
        parse_error("dictionary path already set")
    opts.dictionary_path = value
    opts.dictionary_set = True

SIMPLE_LONG = {
    'stdout', 'decompress', 'force', 'help', 'rm', 'squash', 'keep',
    'no-copy-stat', 'test', 'verbose', 'concatenated', 'version', 'best'
}
PARAM_LONG = {'output', 'quality', 'lgwin', 'large_window', 'comment', 'dictionary', 'suffix'}

def apply_long(opts, name, value, has_value, original):
    if name == 'help' and not has_value:
        sys.stderr.write(help_text())
        raise SystemExit(0)
    if name == 'version' and not has_value:
        sys.stdout.write(VERSION + "\n")
        raise SystemExit(0)
    if has_value:
        if value == "":
            if name in PARAM_LONG or name not in SIMPLE_LONG:
                parse_error(f"must pass the parameter as --{name}=value")
            else:
                parse_error(f"invalid parameter: [{name}=]")
        if name not in PARAM_LONG:
            parse_error(f"invalid parameter: [{name}={value}]")
        if name == 'output':
            set_output(opts, value, '--output')
        elif name == 'quality':
            set_quality(opts, parse_quality_value(value))
        elif name == 'lgwin':
            set_lgwin(opts, parse_lgwin_value(value, False), False)
        elif name == 'large_window':
            set_lgwin(opts, parse_lgwin_value(value, True), True)
        elif name == 'comment':
            set_comment(opts, value, '--comment')
        elif name == 'dictionary':
            set_dictionary(opts, value, '--dictionary')
        elif name == 'suffix':
            set_suffix(opts, value, '--suffix')
        return
    # No =value.
    if name not in SIMPLE_LONG:
        parse_error(f"must pass the parameter as --{name}=value")
    if name == 'stdout':
        if opts.mode == 'test': opts.test_conflict = True
        set_stdout(opts)
    elif name == 'decompress':
        set_mode(opts, 'decompress', '--decompress')
    elif name == 'force':
        if opts.force_set: parse_error("force output overwrite already set")
        opts.force = True; opts.force_set = True
    elif name == 'rm':
        set_keep_rm(opts, True)
    elif name == 'squash':
        if opts.squash_set: parse_error("argument --squash / -s already set")
        opts.squash = True; opts.squash_set = True
    elif name == 'keep':
        set_keep_rm(opts, False)
    elif name == 'no-copy-stat':
        if opts.copy_stat_set: parse_error("argument --no-copy-stat / -n already set")
        opts.copy_stat = False; opts.copy_stat_set = True
    elif name == 'test':
        if opts.stdout_set or opts.concatenated: opts.test_conflict = True
        set_mode(opts, 'test', '--test')
    elif name == 'verbose':
        if opts.verbose_set: parse_error("argument --verbose / -v already set")
        opts.verbose = True; opts.verbose_set = True
    elif name == 'concatenated':
        if opts.mode == 'test': opts.test_conflict = True
        if opts.concatenated_set: parse_error("argument -K / --concatenated already set")
        opts.concatenated = True; opts.concatenated_set = True
    elif name == 'best':
        set_quality(opts, 11)


def parse_args(argv):
    opts = Options()
    prog = os.path.basename(sys.argv[0])
    if prog == 'brcat':
        opts.mode = 'decompress'; opts.concatenated = True; opts.stdout = True; opts.stdout_set = True
    elif prog == 'unbrotli':
        opts.mode = 'decompress'

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == '--':
            opts.files.extend(argv[i+1:])
            break
        if arg == '-' or not arg.startswith('-'):
            opts.files.append(arg); i += 1; continue
        if arg.startswith('--'):
            body = arg[2:]
            if '=' in body:
                name, value = body.split('=', 1)
                apply_long(opts, name, value, True, arg)
            else:
                apply_long(opts, body, None, False, arg)
            i += 1; continue
        # short options can be coalesced, but options with parameters consume
        # the next argv element only (attached forms like -q5 are rejected).
        j = 1
        while j < len(arg):
            ch = arg[j]
            arepr = '-' + ch
            if ch.isdigit():
                set_quality(opts, int(ch)); j += 1; continue
            if ch in ('q','w','o','C','D','S'):
                if j != len(arg) - 1:
                    parse_error(f"expected parameter for argument {arepr}")
                if i + 1 >= len(argv) or argv[i+1] == "":
                    parse_error(f"expected parameter for argument {arepr}")
                val = argv[i+1]
                if ch == 'q': set_quality(opts, parse_quality_value(val))
                elif ch == 'w': set_lgwin(opts, parse_lgwin_value(val, False), False)
                elif ch == 'o': set_output(opts, val, '-o')
                elif ch == 'C': set_comment(opts, val, '-C')
                elif ch == 'D': set_dictionary(opts, val, '-D')
                elif ch == 'S': set_suffix(opts, val, '-S')
                i += 1
                j += 1
                break
            elif ch == 'c':
                if opts.mode == 'test': opts.test_conflict = True
                set_stdout(opts)
            elif ch == 'd':
                set_mode(opts, 'decompress', '-d')
            elif ch == 'f':
                if opts.force_set: parse_error("force output overwrite already set")
                opts.force = True; opts.force_set = True
            elif ch == 'h':
                sys.stderr.write(help_text()); raise SystemExit(0)
            elif ch == 'j':
                set_keep_rm(opts, True)
            elif ch == 's':
                if opts.squash_set: parse_error("argument --squash / -s already set")
                opts.squash = True; opts.squash_set = True
            elif ch == 'k':
                set_keep_rm(opts, False)
            elif ch == 'n':
                if opts.copy_stat_set: parse_error("argument --no-copy-stat / -n already set")
                opts.copy_stat = False; opts.copy_stat_set = True
            elif ch == 't':
                if opts.stdout_set or opts.concatenated: opts.test_conflict = True
                set_mode(opts, 'test', '-t')
            elif ch == 'v':
                if opts.verbose_set: parse_error("argument --verbose / -v already set")
                opts.verbose = True; opts.verbose_set = True
            elif ch == 'K':
                if opts.mode == 'test': opts.test_conflict = True
                if opts.concatenated_set: parse_error("argument -K / --concatenated already set")
                opts.concatenated = True; opts.concatenated_set = True
            elif ch == 'V':
                sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
            elif ch == 'Z':
                set_quality(opts, 11)
            else:
                parse_error(f"invalid argument -{ch}")
            j += 1
        i += 1

    # Silent validation failures in the reference print just the usage block.
    if opts.mode == 'test' and (opts.stdout_set or opts.concatenated or opts.test_conflict):
        parse_error(None)
    if opts.stdout and len(opts.files) > 1:
        parse_error(None)
    if opts.squash and opts.stdout:
        parse_error(None)
    return opts

class Brotli:
    def __init__(self):
        self.enc = ctypes.CDLL('libbrotlienc.so.1')
        self.dec = ctypes.CDLL('libbrotlidec.so.1')
        self.enc.BrotliEncoderCreateInstance.argtypes = [c_void_p, c_void_p, c_void_p]
        self.enc.BrotliEncoderCreateInstance.restype = c_void_p
        self.enc.BrotliEncoderDestroyInstance.argtypes = [c_void_p]
        self.enc.BrotliEncoderSetParameter.argtypes = [c_void_p, c_int, c_uint]
        self.enc.BrotliEncoderSetParameter.restype = c_int
        self.enc.BrotliEncoderCompressStream.argtypes = [c_void_p, c_int, POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t)]
        self.enc.BrotliEncoderCompressStream.restype = c_int
        self.enc.BrotliEncoderIsFinished.argtypes = [c_void_p]
        self.enc.BrotliEncoderIsFinished.restype = c_int
        self.dec.BrotliDecoderCreateInstance.argtypes = [c_void_p, c_void_p, c_void_p]
        self.dec.BrotliDecoderCreateInstance.restype = c_void_p
        self.dec.BrotliDecoderDestroyInstance.argtypes = [c_void_p]
        self.dec.BrotliDecoderSetParameter.argtypes = [c_void_p, c_int, c_uint]
        self.dec.BrotliDecoderSetParameter.restype = c_int
        self.dec.BrotliDecoderDecompressStream.argtypes = [c_void_p, POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t), POINTER(POINTER(c_uint8)), POINTER(c_size_t)]
        self.dec.BrotliDecoderDecompressStream.restype = c_int

    def _set_param(self, st, param, value):
        return self.enc.BrotliEncoderSetParameter(st, param, value)

    def compress(self, data, quality, lgwin, use_large=False, comment=None):
        q_eff = 11 if quality == 10 else quality
        if len(data) == 0 and not comment:
            return empty_stream_bytes(quality, q_eff, lgwin, use_large)
        st = self.enc.BrotliEncoderCreateInstance(None, None, None)
        if not st:
            raise RuntimeError('encoder create failed')
        try:
            # BrotliEncoderParameter: MODE=0, QUALITY=1, LGWIN=2, SIZE_HINT=5,
            # LARGE_WINDOW=6. These are stable public API values.
            self._set_param(st, 1, q_eff)
            self._set_param(st, 2, lgwin)
            if use_large:
                self._set_param(st, 6, 1)
            self._set_param(st, 5, min(len(data), 0xffffffff))
            out_parts = []
            def call_stream(op, payload):
                arr = (c_uint8 * max(1, len(payload))).from_buffer_copy(payload if payload else b'\0')
                next_in = ctypes.cast(arr, POINTER(c_uint8))
                avail_in = c_size_t(len(payload))
                while True:
                    outbuf = (c_uint8 * 65536)()
                    next_out = ctypes.cast(outbuf, POINTER(c_uint8))
                    avail_out = c_size_t(65536)
                    total = c_size_t(0)
                    ok = self.enc.BrotliEncoderCompressStream(st, op, byref(avail_in), byref(next_in), byref(avail_out), byref(next_out), byref(total))
                    produced = 65536 - avail_out.value
                    if produced:
                        out_parts.append(bytes(outbuf[:produced]))
                    if not ok:
                        raise RuntimeError('compression failed')
                    if avail_in.value == 0 and avail_out.value > 0:
                        break
            if comment:
                call_stream(BROTLI_OPERATION_EMIT_METADATA, comment)
            arr = (c_uint8 * max(1, len(data))).from_buffer_copy(data if data else b'\0')
            next_in = ctypes.cast(arr, POINTER(c_uint8))
            avail_in = c_size_t(len(data))
            while not self.enc.BrotliEncoderIsFinished(st):
                outbuf = (c_uint8 * 65536)()
                next_out = ctypes.cast(outbuf, POINTER(c_uint8))
                avail_out = c_size_t(65536)
                total = c_size_t(0)
                ok = self.enc.BrotliEncoderCompressStream(st, BROTLI_OPERATION_FINISH, byref(avail_in), byref(next_in), byref(avail_out), byref(next_out), byref(total))
                produced = 65536 - avail_out.value
                if produced:
                    out_parts.append(bytes(outbuf[:produced]))
                if not ok:
                    raise RuntimeError('compression failed')
            return b''.join(out_parts)
        finally:
            self.enc.BrotliEncoderDestroyInstance(st)

    def decompress_one(self, data):
        st = self.dec.BrotliDecoderCreateInstance(None, None, None)
        if not st:
            raise RuntimeError('decoder create failed')
        try:
            # Enable non-RFC large-window streams; the reference decoder accepts
            # them without requiring the flag on the command line.
            self.dec.BrotliDecoderSetParameter(st, 1, 1)
            arr = (c_uint8 * max(1, len(data))).from_buffer_copy(data if data else b'\0')
            base_addr = ctypes.addressof(arr)
            next_in = ctypes.cast(arr, POINTER(c_uint8))
            avail_in = c_size_t(len(data))
            out_parts = []
            while True:
                outbuf = (c_uint8 * 65536)()
                next_out = ctypes.cast(outbuf, POINTER(c_uint8))
                avail_out = c_size_t(65536)
                total = c_size_t(0)
                res = self.dec.BrotliDecoderDecompressStream(st, byref(avail_in), byref(next_in), byref(avail_out), byref(next_out), byref(total))
                produced = 65536 - avail_out.value
                if produced:
                    out_parts.append(bytes(outbuf[:produced]))
                if res == BROTLI_DECODER_RESULT_SUCCESS:
                    cur_addr = ctypes.cast(next_in, c_void_p).value or base_addr
                    consumed = cur_addr - base_addr
                    return True, b''.join(out_parts), consumed
                if res == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT:
                    continue
                if res == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT:
                    cur_addr = ctypes.cast(next_in, c_void_p).value or base_addr
                    consumed = cur_addr - base_addr
                    return False, b''.join(out_parts), consumed
                # ERROR
                cur_addr = ctypes.cast(next_in, c_void_p).value or base_addr
                consumed = max(0, cur_addr - base_addr)
                return False, b''.join(out_parts), consumed
        finally:
            self.dec.BrotliDecoderDestroyInstance(st)

    def decompress(self, data, concatenated=False):
        pos = 0
        out_parts = []
        if concatenated:
            while pos < len(data):
                ok, out, consumed = self.decompress_one(data[pos:])
                out_parts.append(out)
                if not ok or consumed <= 0:
                    return False, b''.join(out_parts), pos + max(consumed, 0)
                pos += consumed
            return True, b''.join(out_parts), pos
        ok, out, consumed = self.decompress_one(data)
        if not ok:
            return False, out, consumed
        if consumed != len(data):
            return False, out, consumed
        return True, out, consumed


def auto_lgwin(n):
    if n <= 0:
        return 10
    w = (n + 15).bit_length()  # ceil(log2(n + 16))
    if w < 10:
        w = 10
    if w > 24:
        w = 24
    return w


def empty_stream_bytes(orig_quality, q_eff, w, use_large):
    if use_large and w > 24:
        if orig_quality <= 2:
            return bytes([0x3f])
        return bytes([0x11, 0xC0 + w])
    if q_eff <= 1:
        if w <= 18:
            return bytes([0x33])
        return bytes([0x33 + 2 * (w - 18)])
    if 10 <= w <= 15:
        return bytes([0xA1 + 0x10 * (w - 10), 0x01])
    if w == 16:
        return bytes([0x06])
    if w == 17:
        return bytes([0x81, 0x01])
    if w <= 18:
        return bytes([0x33])
    return bytes([0x33 + 2 * (w - 18)])


def effective_window(opts, input_len):
    if opts.lgwin is None or opts.lgwin == 0:
        return auto_lgwin(input_len), False
    use_large = opts.large_window and opts.lgwin > 24
    return opts.lgwin, use_large

# Practical extractor for the initial metadata block emitted by the encoder for
# --comment (length <= 80). The public decoder discards metadata, so validation
# needs this lightweight header recognizer.
def extract_initial_metadata(data):
    n = len(data)
    # Large-window metadata, quality >= 3: 11 99..9e LL ... payload at 4.
    if n >= 4 and data[0] == 0x11 and 0x99 <= data[1] <= 0x9e and (data[2] & 0x0f) == 0x05:
        l = ((data[2] >> 4) | (data[3] << 4)) + 1
        if 1 <= l <= 80 and n >= 4 + l:
            return True, data[4:4+l]
    # Window 16 metadata: byte0 is 0x2c or 0xac; length low bit is byte0 bit7.
    if n >= 2 and (data[0] & 0x7f) == 0x2c:
        l = (((data[0] >> 7) & 1) | (data[1] << 1)) + 1
        if 1 <= l <= 80 and n >= 2 + l:
            return True, data[2:2+l]
    # Windows 10..15 and 17: length low three bits live in byte1 bits 5..7.
    if n >= 3 and (data[1] & 0x1f) == 0x0b:
        l = ((data[1] >> 5) | (data[2] << 3)) + 1
        if 1 <= l <= 80 and n >= 3 + l:
            return True, data[3:3+l]
    # Low-quality/small-window and windows 18..24: length low six bits in byte1.
    if n >= 3 and data[0] in (0x63,0x65,0x67,0x69,0x6b,0x6d,0x6f) and (data[1] & 0x03) == 0x01:
        l = ((data[1] >> 2) | (data[2] << 6)) + 1
        if 1 <= l <= 80 and n >= 3 + l:
            return True, data[3:3+l]
    return False, None


def file_error(kind, path, exc):
    sys.stderr.write(f"failed to open {kind} file [{path}]: {exc.strerror or str(exc)}\n")


def read_file(path):
    try:
        with open(path, 'rb') as f:
            return f.read()
    except OSError as e:
        file_error('input', path, e)
        return None


def check_output_available(path, force):
    if not force and os.path.exists(path):
        sys.stderr.write(f"failed to open output file [{path}]: File exists\n")
        return False
    # Try opening later; parent/permission errors are reported then.
    return True


def write_output_file(path, data, force):
    mode = 'wb' if force else 'xb'
    try:
        with open(path, mode) as f:
            f.write(data)
        return True
    except OSError as e:
        file_error('output', path, e)
        return False


def derive_decompress_name(path, suffix):
    if len(path) <= len(suffix):
        sys.stderr.write(f"empty output file name for [{path}] input file\n")
        return None
    if not path.endswith(suffix):
        sys.stderr.write(f"input file [{path}] suffix mismatch\n")
        return None
    out = path[:-len(suffix)]
    if out == '':
        sys.stderr.write(f"empty output file name for [{path}] input file\n")
        return None
    return out


def copy_stat(src, dst):
    try:
        shutil.copystat(src, dst, follow_symlinks=True)
    except Exception:
        pass


def verbose_line(kind, label, in_size, out_size, start):
    elapsed = time.time() - start
    # The original rounds to two decimals; benchmark actions are small, so this
    # usually prints 0.00 just like the reference.
    sys.stderr.write(f"{kind} [{label}]: {in_size} B -> {out_size} B in {elapsed:.2f} sec\n")


def process(opts):
    # Open dictionary file for matching diagnostics. The system public library
    # used here has no custom raw-dictionary entry points, so the data is not
    # otherwise consumed; normal Brotli behavior is preserved for the common CLI.
    if opts.dictionary_path is not None:
        try:
            with open(opts.dictionary_path, 'rb') as f:
                _ = f.read()
        except OSError as e:
            sys.stderr.write(f"failed to open dictionary file [{opts.dictionary_path}]: {e.strerror or str(e)}\n")
            return 1
    br = Brotli()
    files = opts.files if opts.files else ['-']
    rc = 0
    for entry in files:
        is_stdin = (entry == '-')
        label = 'con' if is_stdin else entry
        if is_stdin:
            try:
                data = sys.stdin.buffer.read()
            except Exception as e:
                sys.stderr.write(f"failed to read input [con]: {e}\n")
                return 1
        else:
            data = read_file(entry)
            if data is None:
                return 1

        start = time.time()
        cmd = opts.command
        out_to_stdout = False
        out_path = None
        if cmd == 'test':
            out_to_stdout = False
        elif opts.output is not None:
            out_path = opts.output
        elif opts.stdout or is_stdin:
            out_to_stdout = True
        elif cmd == 'compress':
            out_path = entry + opts.suffix
        else:
            out_path = derive_decompress_name(entry, opts.suffix)
            if out_path is None:
                return 1

        if out_path is not None:
            if not check_output_available(out_path, opts.force):
                return 1

        if cmd == 'compress':
            w, use_large = effective_window(opts, len(data))
            comment = opts.comment if (opts.comment_set and opts.comment) else None
            try:
                out = br.compress(data, opts.quality, w, use_large, comment)
            except Exception:
                sys.stderr.write(f"failed to compress input [{label}]\n")
                return 1
            kept_output = True
            if opts.squash and out_path is not None and len(out) > len(data):
                # Destination is suppressed/removed if it would be larger.
                try:
                    if os.path.exists(out_path):
                        os.remove(out_path)
                except Exception:
                    pass
                kept_output = False
            elif out_to_stdout:
                try:
                    sys.stdout.buffer.write(out)
                    sys.stdout.buffer.flush()
                except BrokenPipeError:
                    return 1
            elif out_path is not None:
                if not write_output_file(out_path, out, opts.force):
                    return 1
                if opts.copy_stat and not is_stdin:
                    copy_stat(entry, out_path)
            if opts.verbose:
                verbose_line('Compressed', label, len(data), len(out), start)
            if opts.remove and kept_output and not is_stdin:
                try: os.remove(entry)
                except OSError: pass
        else:
            # Comment validation: absent comments are reported as "corrupt" but
            # (quirkily) do not cause a failing status; mismatches do fail.
            absent_comment_warning = False
            if opts.comment_set and opts.comment:
                found, meta = extract_initial_metadata(data)
                if found:
                    if meta != opts.comment:
                        sys.stderr.write(f"corrupt input [{label}]\n")
                        return 1
                else:
                    absent_comment_warning = True
            ok, out, consumed = br.decompress(data, opts.concatenated)
            if not ok:
                if out_to_stdout:
                    try:
                        sys.stdout.buffer.write(out); sys.stdout.buffer.flush()
                    except BrokenPipeError:
                        return 1
                sys.stderr.write(f"corrupt input [{label}]\n")
                return 1
            if cmd != 'test':
                if out_to_stdout:
                    try:
                        sys.stdout.buffer.write(out); sys.stdout.buffer.flush()
                    except BrokenPipeError:
                        return 1
                elif out_path is not None:
                    if not write_output_file(out_path, out, opts.force):
                        return 1
                    if opts.copy_stat and not is_stdin:
                        copy_stat(entry, out_path)
            if opts.verbose:
                verbose_line('Decompressed', label, len(data), len(out), start)
            if absent_comment_warning:
                sys.stderr.write(f"corrupt input [{label}]\n")
            if opts.remove and not is_stdin:
                try: os.remove(entry)
                except OSError: pass
    return rc


def main():
    try:
        opts = parse_args(sys.argv[1:])
    except ParseExit as e:
        if e.help_to_stdout:
            sys.stdout.write(help_text())
        else:
            sys.stderr.write(help_text())
        if e.msg:
            sys.stderr.write(str(e.msg) + "\n")
        return e.code
    return process(opts)

if __name__ == '__main__':
    try:
        sys.exit(main())
    except SystemExit:
        raise
    except Exception as e:
        sys.stderr.write(str(e) + "\n")
        sys.exit(1)
